// Subscribe dynamically so the application ID and DevEUI stay out of the flow export.
// Set IRRIGATION_APP_ID and PUMP_DEV_EUI in this node's Environment tab,
// or once in process env for the Node-RED service.
const app = String(env.get("IRRIGATION_APP_ID") || "").toLowerCase();
const eui = String(env.get("PUMP_DEV_EUI") || "").toLowerCase();
if (!/^[a-f0-9-]{36}$/.test(app) || !/^[a-f0-9]{16}$/.test(eui)) {
    node.status({ fill: "red", shape: "ring", text: "IRRIGATION_APP_ID / PUMP_DEV_EUI missing" });
    return null;
}
const topic = "application/" + app + "/device/" + eui + "/event/+";
node.status({ fill: "green", shape: "dot", text: topic });
return { action: "subscribe", topic: topic, qos: 0 };

const app = String(env.get("IRRIGATION_APP_ID") || "").toLowerCase();
const eui = String(env.get("PUMP_DEV_EUI") || "").toLowerCase();
const parts = String(msg.topic || "").split("/");
if (parts.length !== 6 || parts[0] !== "application" || parts[1] !== app ||
    parts[2] !== "device" || parts[3].toLowerCase() !== eui ||
    parts[4] !== "event" || parts[5] !== "up") return null;
let event = msg.payload;
try {
  if (Buffer.isBuffer(event)) event = JSON.parse(event.toString("utf8"));
  else if (typeof event === "string") event = JSON.parse(event);
} catch (error) {
  node.warn("Invalid ChirpStack event JSON: " + error.message);
  return null;
}
if (!event || event.fPort !== 51) return null;
let d = event.object;
if (!d || typeof d !== "object" || d.command_result === undefined) {
  let b;
  try { b = Buffer.from(event.data || "", "base64"); } catch (_) { return null; }
  if (b.length !== 17 || b[0] !== 1) {
    node.warn("Pump status requires protocol v1, FPort 51, 17 bytes");
    return null;
  }
  const u16 = i => (b[i] << 8) | b[i + 1];
  const results = ["none", "accepted", "failed", "duplicate", "invalid", "storage_error"];
  const states = ["unknown", "forward", "reverse", "stopped"];
  d = {
    communication_ok: !!(b[1] & 1),
    configuration_valid: !!(b[1] & 2),
    running: !!(b[1] & 4),
    frequency_armed: !!(b[1] & 8),
    lorawan_active: !!(b[1] & 16),
    class_c_active: !!(b[1] & 32),
    command_result: results[b[2]] || "unknown",
    last_command_id: u16(3) === 65535 ? null : u16(3),
    commanded_frequency_hz: u16(5) / 100,
    actual_frequency_hz: u16(7) / 100,
    motor_current_a: u16(9) / 100,
    vfd_fault_code: u16(11),
    output_voltage_v: u16(13) / 10,
    run_state: states[b[15]] || "unknown",
    communication_error_code: b[16]
  };
}
const now = Date.now();
const s = flow.get("pump_state") || {};
Object.assign(s, d);
s.last_seen = event.time || new Date(now).toISOString();
s.last_seen_ms = now;
s.stale = false;
s.f_port = event.fPort;
const rx = Array.isArray(event.rxInfo) ? event.rxInfo : [];
if (rx.length) {
  const best = rx.reduce((a, b) => Number(b.snr) > Number(a.snr) ? b : a);
  s.rssi = best.rssi;
  s.snr = best.snr;
}
const reportedId = d.last_command_id == null ? NaN : Number(d.last_command_id);
const next = flow.get("pump_next_id");
if (Number.isInteger(reportedId) && reportedId >= 0 && reportedId <= 65534) {
  const expected = (reportedId + 1) % 65535;
  if (!Number.isInteger(next) || next < 0 || next > 65534 ||
      (next !== expected && ((expected - next + 65535) % 65535) < 32767)) {
    flow.set("pump_next_id", expected);
  }
} else if (!Number.isInteger(next)) {
  flow.set("pump_next_id", 0);
}
const pending = flow.get("pump_pending");
if (pending && Number.isInteger(reportedId) && reportedId === pending.id) {
  s.command_state = d.command_result;
  s.last_command = pending;
  flow.set("pump_pending", null);
}
s.pending = flow.get("pump_pending") || null;
flow.set("pump_state", s);
msg.payload = {kind: "state", state: s};
return msg;

const s = flow.get("pump_state") || {};
const now = Date.now();
s.stale = !s.last_seen_ms || now - s.last_seen_ms > 150000;
const pending = flow.get("pump_pending");
if (pending && now - pending.queued_at_ms > 150000) {
  s.command_state = "no device confirmation";
  s.last_command = pending;
  s.pending = null;
  flow.set("pump_pending", null);
} else {
  s.pending = pending || null;
}
flow.set("pump_state", s);
msg.payload = {kind: "state", state: s};
return msg;

const app = String(env.get("IRRIGATION_APP_ID") || "").toLowerCase();
const eui = String(env.get("PUMP_DEV_EUI") || "").toLowerCase();
const action = msg.payload || {};
if (action.kind !== "command") return null;
const s = flow.get("pump_state") || {};
function reply(error) {
  s.ui_error = error;
  flow.set("pump_state", s);
  return [null, {payload: {kind: "state", state: s}}];
}
const operations = {stop: 1, estop: 2, set_frequency: 3, start: 4};
const op = operations[action.command];
if (!op) return reply("Unknown pump command.");
let arg = 0;
if (op === 3) {
  const hz = Number(action.frequency_hz);
  if (!Number.isFinite(hz) || hz < 10 || hz > 50)
    return reply("Frequency must be 10 to 50 Hz.");
  arg = Math.round(hz * 100);
}
const pending = flow.get("pump_pending");
if (pending && op !== 1) return reply("Wait for the current command result. Stop remains available.");
if (!s.last_seen_ms) return reply("Wait for a Pump status uplink before sending commands.");
if (op !== 1 && Date.now() - s.last_seen_ms > 150000)
  return reply("Pump status is stale. Wait for a new uplink.");
const id = flow.get("pump_next_id");
if (!Number.isInteger(id) || id < 0 || id > 65534)
  return reply("Wait for a status uplink to synchronize command IDs.");
flow.set("pump_next_id", (id + 1) % 65535);
const bytes = Buffer.from([1, op, id >> 8, id & 255, arg >> 8, arg & 255]);
const current = {id, command: action.command, frequency_hz: op === 3 ? arg / 100 : null,
  queued_at: new Date().toISOString(), queued_at_ms: Date.now()};
flow.set("pump_pending", current);
s.pending = current;
s.last_command = current;
s.command_state = "queued";
s.ui_error = pending && op === 1
  ? "Stop queued. A previous downlink may still be waiting in ChirpStack."
  : "";
flow.set("pump_state", s);
return [{
  topic: "application/" + app + "/device/" + eui + "/command/down",
  payload: JSON.stringify({devEui: eui, confirmed: false, fPort: 50,
    data: bytes.toString("base64")}),
  qos: "0",
  retain: false
}, {payload: {kind: "state", state: s}}];

let event = msg.payload;
try {
  if (Buffer.isBuffer(event)) event = JSON.parse(event.toString("utf8"));
  else if (typeof event === "string") event = JSON.parse(event);
} catch (_) { return msg; }
if (!event || event.fPort !== 51) return msg;
if (!event.object || typeof event.object !== "object" || event.object.command_result === undefined) {
  let b;
  try { b = Buffer.from(event.data || "", "base64"); } catch (_) { return msg; }
  if (b.length === 22 && b[0] === 2) {
    const u16 = i => (b[i] << 8) | b[i + 1];
    const s16 = i => { const v = u16(i); return v >= 32768 ? v - 65536 : v; };
    const results = ["none","accepted","failed","duplicate","invalid","storage_error"];
    const states = ["unknown","forward","reverse","stopped"];
    const joinError = s16(17);
    event.object = {communication_ok:!!(b[1]&1),configuration_valid:!!(b[1]&2),running:!!(b[1]&4),frequency_armed:!!(b[1]&8),lorawan_active:!!(b[1]&16),class_c_active:!!(b[1]&32),command_result:results[b[2]]||"unknown",last_command_id:u16(3)===65535?null:u16(3),commanded_frequency_hz:u16(5)/100,actual_frequency_hz:u16(7)/100,motor_current_a:u16(9)/100,vfd_fault_code:u16(11),output_voltage_v:u16(13)/10,run_state:states[b[15]]||"unknown",communication_error_code:b[16],previous_join_error_code:joinError,previous_join_error:joinError===-1116?"No OTAA JoinAccept received in RX1/RX2":joinError===0?"None":"RadioLib error "+joinError,join_attempt_count:b[19],previous_join_retry_seconds:u16(20)};
    msg.payload = event;
  }
}
const s = flow.get("pump_state") || {};
if (s.refresh_pending) {
  s.refresh_pending = false;
  s.refresh_result = "Status received";
  s.refresh_completed_at = new Date().toISOString();
  flow.set("pump_state", s);
}
return msg;

const app=String(env.get("IRRIGATION_APP_ID") || "").toLowerCase();
const eui=String(env.get("PUMP_DEV_EUI") || "").toLowerCase();
const action=msg.payload||{};
if(action.kind!=="refresh")return null;
const now=Date.now();
const last=Number(flow.get("pump_last_refresh_ms")||0);
const s=flow.get("pump_state")||{};
if(now-last<10000){s.refresh_result="Refresh rate limit: try again in "+Math.ceil((10000-(now-last))/1000)+" s";flow.set("pump_state",s);return[null,{payload:{kind:"state",state:s}}];}
if(s.refresh_pending&&now-Number(s.refresh_requested_at_ms||0)<30000){s.refresh_result="A status request is already pending.";flow.set("pump_state",s);return[null,{payload:{kind:"state",state:s}}];}
flow.set("pump_last_refresh_ms",now);
s.refresh_pending=true;s.refresh_requested_at_ms=now;s.refresh_requested_at=new Date(now).toISOString();s.refresh_result="Requesting…";flow.set("pump_state",s);
return[{topic:"application/"+app+"/device/"+eui+"/command/down",payload:JSON.stringify({devEui:eui,confirmed:false,fPort:50,data:Buffer.from([1,5]).toString("base64")}),qos:"0",retain:false},{payload:{kind:"state",state:s}}];

const source=(msg.payload&&msg.payload.state)||{};
const s=Object.assign({},source);
function readableTime(value){
  if(!value)return value;
  const normalized=String(value).replace(/(\.\d{3})\d+/,"$1");
  const date=new Date(normalized);
  if(Number.isNaN(date.getTime()))return value;
  const parts=new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Tashkent",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false}).formatToParts(date);
  const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));
  return p.day+"/"+p.month+"/"+p.year+" "+p.hour+":"+p.minute+":"+p.second;
}
s.last_seen=readableTime(s.last_seen);
if(s.pending)s.pending=Object.assign({},s.pending,{queued_at:readableTime(s.pending.queued_at)});
if(s.last_command)s.last_command=Object.assign({},s.last_command,{queued_at:readableTime(s.last_command.queued_at)});
msg.payload={kind:"state",state:s};
return msg;

const action=msg.payload||{};
if(action.kind==="refresh")return[null,msg,null];
const s=flow.get("pump_state")||{};
const offlineAfterMs=s.running?45000:75000;
if(action.kind==="command"&&action.command!=="stop"&&(!s.last_seen_ms||Date.now()-s.last_seen_ms>offlineAfterMs)){
  s.ui_error="Pump status is offline. Wait for a fresh uplink. Stop remains available.";
  flow.set("pump_state",s);
  return[null,null,{payload:{kind:"state",state:s}}];
}
return[msg,null,null];

const source=(msg.payload&&msg.payload.state)||{};
const s=Object.assign({},source);
const offlineAfterMs=source.running?45000:75000;
s.offline_after_seconds=offlineAfterMs/1000;
s.stale=!s.last_seen_ms||Date.now()-s.last_seen_ms>offlineAfterMs;
if(s.stale){
  s.class_c_active=false;
  s.lorawan_active=false;
  s.communication_ok=null;
  s.vfd_fault_code=null;
}
msg.payload={kind:"state",state:s};
return msg;

let event = msg.payload;
try {
  if (Buffer.isBuffer(event)) event = JSON.parse(event.toString("utf8"));
  else if (typeof event === "string") event = JSON.parse(event);
} catch (_) { return msg; }
if (!event || event.fPort !== 51) return msg;
let bytes;
try { bytes = Buffer.from(event.data || "", "base64"); } catch (_) { return msg; }
if (bytes.length === 22 && bytes[0] === 2) {
  if (!event.object || typeof event.object !== "object") event.object = {};
  event.object.manual_mode = !!(bytes[1] & 64);
  msg.payload = event;
}
return msg;

const s=(msg.payload&&msg.payload.state)||{};
if(s.command_result==="in_progress"&&s.last_command){
  s.command_state="in progress: waiting for final VFD condition";
  s.pending=s.last_command;
  flow.set("pump_pending",s.last_command);
  flow.set("pump_state",s);
}
return msg;
